{"rob": "robolang 1.3;

task relay(robot arm, object box, location src, location handoff, robot amr, location conveyor, region aisle) {
    goal { object_at box conveyor; }
    plan {
        grasp arm box;
        move arm to handoff;
        place arm box at handoff;
        wait until region_clear aisle timeout 30 s;
        move amr to handoff;
        grasp amr box;
        move amr to conveyor;
        place amr box at conveyor;
    }
}
", "task": "relay", "bindings": [{"param": "arm", "id": "arm1"}, {"param": "box", "id": "box1"}, {"param": "src", "id": "shelf_a"}, {"param": "handoff", "id": "handoff"}, {"param": "amr", "id": "amr1"}, {"param": "conveyor", "id": "conveyor"}, {"param": "aisle", "id": "aisle"}]}
